-- Sauvegarder la V3 et vérifier les colonnes avant exécution. Aucun DROP, aucune donnée supprimée.
ALTER TABLE tvp_articles ADD COLUMN IF NOT EXISTS video_source_url VARCHAR(1300) NULL;
ALTER TABLE tvp_shows ADD COLUMN IF NOT EXISTS intro_video_url VARCHAR(1300) NULL;
CREATE TABLE IF NOT EXISTS tvp_program_slots (id CHAR(36) PRIMARY KEY,weekday TINYINT UNSIGNED NOT NULL,start_time TIME NOT NULL,title VARCHAR(180) NOT NULL,category VARCHAR(100) NOT NULL DEFAULT '',INDEX(weekday,start_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tvp_homepage_ad_slots (banner TINYINT UNSIGNED NOT NULL,slot TINYINT UNSIGNED NOT NULL,advertiser VARCHAR(120) NOT NULL DEFAULT '',image_url VARCHAR(700) NOT NULL DEFAULT '',target_url VARCHAR(700) NOT NULL DEFAULT '',alt VARCHAR(300) NOT NULL DEFAULT '',active TINYINT(1) NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,updated_at DATETIME(6) NULL,PRIMARY KEY(banner,slot)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO tvp_homepage_ad_slots(banner,slot) SELECT a.n,b.n FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) a CROSS JOIN (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) b;
CREATE TABLE IF NOT EXISTS tvp_editorial_media (id CHAR(36) PRIMARY KEY,kind ENUM('reel','reportage','podcast') NOT NULL,title VARCHAR(200) NOT NULL,description TEXT NOT NULL,category VARCHAR(100) NOT NULL DEFAULT '',source_url VARCHAR(1300) NOT NULL,thumbnail_url VARCHAR(1300) NOT NULL DEFAULT '',duration_seconds INT UNSIGNED NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',published_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,INDEX(kind,status,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tvp_home_editorial_settings (id TINYINT UNSIGNED PRIMARY KEY,media_order JSON NOT NULL,hidden_media JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO tvp_home_editorial_settings VALUES (1,'["reels","ligne-rouge","replays","reportages","podcasts"]','[]');
CREATE TABLE IF NOT EXISTS tvp_live_entitlements (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,starts_at DATETIME(6) NOT NULL,ends_at DATETIME(6) NOT NULL,status ENUM('active','revoked') NOT NULL DEFAULT 'active',reference VARCHAR(200) UNIQUE,INDEX(user_id,status,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tvp_newsletter_subscriptions(id CHAR(36) PRIMARY KEY,email VARCHAR(255) NOT NULL,newsletter VARCHAR(120) NOT NULL,created_at DATETIME(6) NOT NULL,UNIQUE(email,newsletter)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tvp_contacts(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL,subject VARCHAR(200) NOT NULL,message TEXT NOT NULL,created_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tvp_questions(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL,question TEXT NOT NULL,created_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS tvp_restream_connections(id TINYINT UNSIGNED PRIMARY KEY,account_id VARCHAR(100) NOT NULL,account_name VARCHAR(255) NOT NULL,token_ciphertext TEXT NOT NULL,expires_at DATETIME NOT NULL,connected_by CHAR(36) NOT NULL,updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
